<script setup lang="ts">
import { computed, ref, watch, onBeforeUnmount } from 'vue'
import { useI18n } from 'vue-i18n'
import { propertySettlementsApi as api, type SettlementDossierRead, type SettlementDelivery, type SettlementDossierEvent } from '@/api/propertySettlements'
import ActionBar, { type ActionItem } from '@/components/ui/ActionBar.vue'
import PropertyButton from '@/components/property/PropertyButton.vue'
import { propertyError } from '@/components/property/propertyError'
import { formatDate, formatDateTime, formatUtcDateTime } from '@/composables/useFormat'
import SettlementDossierForm from './SettlementDossierForm.vue'
import SettlementDeliveryEditor from './SettlementDeliveryEditor.vue'
import SettlementPersonChangeEditor from './SettlementPersonChangeEditor.vue'
import { blankDossier, blankPersonChange, dossierCopy } from './dossierForm'
import { settlementInput as input, settlementBox as box } from './settlementForm'
const props = defineProps<{ supplier: number; value: SettlementDossierRead; manage: boolean; periodFrom: string; periodTo: string }>()
const emit = defineEmits<{ updated: [] }>(), { t } = useI18n()
const current = ref(props.value), mode = ref<'acceptance' | 'delivery' | 'legal_metadata' | null>(null), dossier = ref(blankDossier()), delivery = ref<SettlementDelivery | null>(null), change = ref(blankPersonChange())
const reason = ref(''), reviewed = ref(false), busy = ref(false), stale = ref(false), error = ref(''), html = ref<HTMLFormElement | null>(null)
let epoch = 0, expected = 0, supersedes: number | null = null, token = crypto.randomUUID()
watch(() => [props.supplier, props.value], () => { epoch++; current.value = props.value; mode.value = null; stale.value = false; busy.value = false; error.value = '' }, { deep: true })
onBeforeUnmount(() => epoch++)
const labels = computed(() => Object.fromEntries(current.value.parties.map(p => [p.id, p.name])))
const person = (id: number | null) => id === null ? t('propertySettlements.dossier.notRecorded') : labels.value[id] || t('propertySettlements.selectedPerson')
function begin(type: 'acceptance' | 'delivery' | 'legal_metadata', receipt?: SettlementDelivery) { if (!props.manage || stale.value || busy.value) return; mode.value = type; expected = current.value.revision_no; reason.value = ''; reviewed.value = false; token = crypto.randomUUID(); error.value = ''; dossier.value = blankDossier(); change.value = blankPersonChange(); delivery.value = receipt ? dossierCopy(receipt) : null; supersedes = receipt ? current.value.delivery_versions[`${receipt.segment_ordinal}:${receipt.recipient_id}`] ?? null : null }
watch([dossier, delivery, change, reason], () => { reviewed.value = false; token = crypto.randomUUID() }, { deep: true })
async function refresh() { const supplier = props.supplier, ticket = ++epoch; busy.value = true; error.value = ''; try { const read = await api.dossier(supplier, current.value.document_id); if (ticket === epoch && supplier === props.supplier) { current.value = read; mode.value = null; stale.value = false } } catch (e) { if (ticket === epoch) error.value = propertyError(e, t) } finally { if (ticket === epoch) busy.value = false } }
async function save() {
 if (!props.manage || busy.value || stale.value || !reviewed.value || !mode.value || !html.value?.reportValidity()) return
 const event: SettlementDossierEvent = mode.value === 'acceptance' ? { type: 'acceptance', dossier: dossierCopy(dossier.value) } : mode.value === 'delivery' && delivery.value ? { type: 'delivery', delivery: dossierCopy(delivery.value), supersedes_event_id: supersedes } : { type: 'legal_metadata', person_change: dossierCopy(change.value) }
 const supplier = props.supplier, ticket = epoch; busy.value = true; error.value = ''
 try { await api.appendDossierEvent(supplier, current.value.document_id, { event, expected_revision: expected, reason: reason.value, idempotency_key: token }); if (ticket === epoch && supplier === props.supplier) { mode.value = null; emit('updated'); busy.value = false; await refresh() } }
 catch (e) { if (ticket === epoch) { stale.value = true; reviewed.value = false; error.value = propertyError(e, t) + ' ' + t('propertySettlements.dossier.conflict') } } finally { if (ticket === epoch) busy.value = false }
}
const actions = computed<ActionItem[]>(() => [{ key: 'append-dossier', label: t('propertySettlements.dossier.append'), icon: 'check', variant: 'success', tier: 'primary', disabled: !props.manage || busy.value || stale.value || !reviewed.value, run: () => { void save() } }, { key: 'cancel-dossier', label: t('propertySettlements.cancel'), icon: 'x', tier: 'secondary', disabled: busy.value, run: () => { mode.value = null } }])
</script>
<template><section :class="box" data-section="external-dossier"><div class="flex flex-wrap items-center justify-between gap-3"><h2 class="font-semibold">{{ t('propertySettlements.dossier.title') }}</h2><PropertyButton icon="cycle" data-action="refresh-dossier" :disabled="busy" @click="refresh">{{ t('propertySettlements.refresh') }}</PropertyButton></div><p class="text-sm text-neutral-500">{{ t('propertySettlements.dossier.metadataOnly') }}</p><p v-if="error" role="alert" class="text-danger-700">{{ error }}</p>
<template v-if="current.dossier"><p>{{ current.dossier.ref }} · {{ current.dossier.issuer.name }} · {{ formatDateTime(current.dossier.issued_at) }}</p><p>{{ t('propertySettlements.dossier.allocation') }}: {{ current.dossier.allocation_ref }}</p><article v-for="segment in current.dossier.segments" :key="segment.ordinal" class="space-y-2 rounded border p-3"><h3>{{ t('propertySettlements.dossier.segment', { number: segment.ordinal }) }} · {{ formatDateTime(segment.valid_from) }} - {{ formatDateTime(segment.valid_to) }}</h3><p>{{ segment.recipient_ids.map(id => person(id)).join(', ') }} · {{ segment.basis_ref }} · {{ segment.allocation_ref }}</p><template v-for="receipt in current.dossier.deliveries" :key="`${receipt.segment_ordinal}:${receipt.recipient_id}`"><div v-if="receipt.segment_ordinal === segment.ordinal" class="space-y-1 border-t pt-2"><h4>{{ person(receipt.recipient_id) }} · {{ t(`propertySettlements.dossier.${receipt.status}`) }}</h4><p>{{ t('propertySettlements.dossier.issuedTo') }}: {{ person(receipt.issued_to_id) }} · {{ t('propertySettlements.dossier.deliveredTo') }}: {{ person(receipt.delivered_to_id) }}</p><p>{{ t('propertySettlements.dossier.deliveredAt') }}: {{ receipt.delivered_at ? formatDateTime(receipt.delivered_at) : t('propertySettlements.dossier.notRecorded') }} · {{ receipt.method ? t(`propertySettlements.dossier.methods.${receipt.method}`) : '' }}</p><p>{{ receipt.recipient_evidence }} {{ receipt.delivery_evidence }}</p><p>{{ t('propertySettlements.dossier.due') }}: {{ receipt.due.date ? formatDate(receipt.due.date) : t('propertySettlements.dossier.notRecorded') }} · {{ receipt.due.basis_ref }}</p><PropertyButton v-if="manage" icon="plus" :disabled="busy || stale" data-action="record-delivery" @click="begin('delivery', receipt)">{{ t('propertySettlements.dossier.recordDelivery') }}</PropertyButton></div></template></article><article v-for="(legal, index) in current.dossier.person_changes" :key="index" class="rounded border p-3"><p>{{ t(`propertySettlements.dossier.roles.${legal.role}`) }}: {{ legal.from_ids.map(id => person(id)).join(', ') }} → {{ legal.to_ids.map(id => person(id)).join(', ') }} · {{ formatDateTime(legal.effective_at) }}</p><p>{{ t(`propertySettlements.dossier.bases.${legal.basis}`) }} · {{ legal.evidence }}</p></article><PropertyButton v-if="manage" icon="plus" :disabled="busy || stale" data-action="record-legal" @click="begin('legal_metadata')">{{ t('propertySettlements.dossier.addChange') }}</PropertyButton></template>
<template v-else><p>{{ t('propertySettlements.dossier.notAccepted') }}</p><PropertyButton v-if="manage" icon="plus" data-action="accept-dossier" :disabled="busy || stale" @click="begin('acceptance')">{{ t('propertySettlements.dossier.accept') }}</PropertyButton></template>
<form v-if="mode" ref="html" class="space-y-3 rounded border border-primary-300 p-3" data-section="dossier-event-form" @submit.prevent="save"><fieldset :disabled="busy || stale || !manage" class="space-y-3"><SettlementDossierForm v-if="mode === 'acceptance'" v-model="dossier" :supplier="supplier" :labels="labels" :period-from="periodFrom" :period-to="periodTo" /><SettlementDeliveryEditor v-if="mode === 'delivery' && delivery" v-model="delivery" :supplier="supplier" :labels="labels" /><SettlementPersonChangeEditor v-if="mode === 'legal_metadata'" v-model="change" :supplier="supplier" :labels="labels" /><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertySettlements.dossier.reason') }}<input v-model="reason" :class="input" required data-field="dossier-reason" /></label><label class="flex flex-wrap items-center gap-2"><input v-model="reviewed" type="checkbox" data-field="dossier-reviewed" />{{ t('propertySettlements.dossier.acknowledgement') }}</label></fieldset><ActionBar :actions="actions" /></form>
<section v-if="current.events.length" class="space-y-2"><h3>{{ t('propertySettlements.dossier.history') }}</h3><article v-for="event in current.events" :key="event.id" class="rounded border p-3"><p>{{ t('propertySettlements.revision', { number: event.revision_no }) }} · {{ formatUtcDateTime(event.recorded_at) }} · {{ t(`propertySettlements.dossier.events.${event.event.type}`) }}</p><p>{{ event.reason }}</p><template v-if="event.event.type === 'delivery'"><p>{{ person(event.event.delivery.recipient_id) }} · {{ t('propertySettlements.dossier.issuedTo') }}: {{ person(event.event.delivery.issued_to_id) }} · {{ t('propertySettlements.dossier.deliveredTo') }}: {{ person(event.event.delivery.delivered_to_id) }} · {{ event.event.delivery.recipient_evidence }} · {{ t(`propertySettlements.dossier.${event.event.delivery.status}`) }} · {{ formatDateTime(event.event.delivery.delivered_at) }} · {{ event.event.delivery.delivery_evidence }} · {{ formatDate(event.event.delivery.due.date) }} · {{ event.event.delivery.due.basis_ref }}</p></template><p v-else-if="event.event.type === 'legal_metadata'">{{ event.event.person_change.evidence }}</p><p v-else>{{ event.event.dossier.ref }}</p></article></section></section></template>
